#ifndef RUNTIME_H
#define RUNTIME_H

/* Runtime files: syntax definitions, colorschemes and help pages.
 * They are embedded in the binary (runtime_data.c, generated by
 * tools/embed.py) and can be overridden/extended by files in the user's
 * config directory, exactly like micro. */

enum { RT_SYNTAX, RT_COLORSCHEME, RT_HELP, RT_NKINDS };

typedef struct {
    const char *name;    /* file name without extension */
    const char *data;
} RtFile;

extern const RtFile rt_syntax_files[];
extern const RtFile rt_colorscheme_files[];
extern const RtFile rt_help_files[];

extern char *config_dir; /* ~/.config/micro (no trailing slash) */

char  *runtime_read(int kind, const char *name); /* malloc'd content or NULL */
char **runtime_list(int kind);                   /* malloc'd names, NULL-terminated */

#endif
